#!/bin/bash
set -euo pipefail

TEST_NAME="async_queue_half_reset"
WORK_DIR="/home/rocket-chip/.hwebench-pr387"
RUN_LOG="$WORK_DIR/run.log"

prepare_sources() {
  mkdir -p /home/rocket-chip/src/main/scala/unittest
  mkdir -p /home/rocket-chip/emulator

  cat > /home/rocket-chip/src/main/scala/unittest/AsyncQueuePR387.scala <<'EOF'
// See LICENSE for license details.

package unittest

import Chisel._
import cde.{Config, CDEMatchError, Parameters}
import rocketchip.BasePlatformConfig
import util.AsyncQueue

class AsyncQueueHalfResetTest extends UnitTest(timeout = 512) {
  val queue = Module(new AsyncQueue(UInt(width = 8), depth = 1, sync = 3))

  val running = Reg(init = Bool(false))
  val cycle = Reg(init = UInt(0, width = 8))
  val sent = Reg(init = Bool(false))
  val recv = Reg(init = Bool(false))
  val recvBits = Reg(init = UInt(0, width = 8))
  val recvCount = Reg(init = UInt(0, width = 2))
  val fireDuringSinkReset = Reg(init = Bool(false))

  when (io.start) { running := Bool(true) }
  when (running && !io.finished) { cycle := cycle + UInt(1) }

  // Hold the sink half in reset, then ask the source half to enqueue.
  // The fix must block the enqueue until reset has cleared.
  val sinkReset = running && cycle >= UInt(2) && cycle < UInt(12)
  val driveValid = running && cycle >= UInt(6) && !sent

  queue.io.enq_clock := clock
  queue.io.enq_reset := reset
  queue.io.deq_clock := clock
  queue.io.deq_reset := reset || sinkReset

  queue.io.enq.valid := driveValid
  queue.io.enq.bits := UInt(0x5a)
  queue.io.deq.ready := Bool(true)

  when (queue.io.enq.fire()) {
    sent := Bool(true)
    when (sinkReset) { fireDuringSinkReset := Bool(true) }
  }

  when (queue.io.deq.fire()) {
    recv := Bool(true)
    recvBits := queue.io.deq.bits
    recvCount := recvCount + UInt(1)
  }

  val doneWindow = running && cycle >= UInt(40)
  io.finished := doneWindow && sent && recv && recvBits === UInt(0x5a) &&
    recvCount === UInt(1) && !fireDuringSinkReset

  assert(!fireDuringSinkReset,
    "AsyncQueue accepted an enqueue while the sink half was held in reset")
  assert(recvCount <= UInt(1),
    "AsyncQueue delivered more than one item after the sink reset sequence")
}

class WithAsyncQueueHalfResetTest extends Config(
  (pname, site, here) => pname match {
    case UnitTests => (p: Parameters) => Seq(
      Module(new AsyncQueueHalfResetTest))
    case _ => throw new CDEMatchError
  })

class AsyncQueueHalfResetConfig
  extends Config(new WithAsyncQueueHalfResetTest ++ new BasePlatformConfig)
EOF

  cat > /home/rocket-chip/emulator/tb_main_pr387.cpp <<'EOF'
#include "VTestHarness.h"
#include "verilated.h"
#include <cstdint>
#include <string>

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);
  Verilated::randReset(2);

  uint64_t max_cycles = 1000;
  for (int i = 1; i < argc; ++i) {
    std::string arg(argv[i]);
    if (arg.rfind("+max-cycles=", 0) == 0) {
      max_cycles = std::stoull(arg.substr(12));
    }
  }

  VTestHarness* top = new VTestHarness;

  for (int i = 0; i < 10; ++i) {
    top->reset = 1;
    top->clock = 0;
    top->eval();
    top->clock = 1;
    top->eval();
  }
  top->reset = 0;

  uint64_t cycles = 0;
  while (!Verilated::gotFinish() && !top->io_success && cycles < max_cycles) {
    top->clock = 0;
    top->eval();
    top->clock = 1;
    top->eval();
    ++cycles;
  }

  const int rc = top->io_success ? 0 : 1;
  top->final();
  delete top;
  return rc;
}
EOF
}

apply_register_router_compat() {
  if grep -q "master_bypass" /home/rocket-chip/src/main/scala/regmapper/RegisterCrossing.scala; then
    perl -0pi -e 's/readCross\.io\.master_allow := Bool\(true\)/readCross.io.master_bypass := Bool(false)/g; s/\n\s*readCross\.io\.slave_allow := Bool\(true\)//g; s/writeCross\.io\.master_allow := Bool\(true\)/writeCross.io.master_bypass := Bool(false)/g; s/\n\s*writeCross\.io\.slave_allow := Bool\(true\)//g' \
      /home/rocket-chip/src/main/scala/uncore/tilelink2/RegisterRouterTest.scala
  fi
}

run_case_inner() {
  cd /home/rocket-chip
  export JAVA_HOME=/opt/jdk8
  export PATH="$JAVA_HOME/bin:$PATH"

  prepare_sources
  apply_register_router_compat

  rm -rf /home/rocket-chip/emulator/generated-src
  mkdir -p /home/rocket-chip/emulator/generated-src

  java -Xmx2G -Xss8M -XX:MaxPermSize=256M -jar /home/rocket-chip/sbt-launch.jar \
    "run-main unittest.Generator /home/rocket-chip/emulator/generated-src unittest TestHarness unittest AsyncQueueHalfResetConfig"

  cd /home/rocket-chip/firrtl
  java -Xmx2G -Xss8M -XX:MaxPermSize=256M -jar /home/rocket-chip/sbt-launch.jar \
    "run-main firrtl.Driver -i /home/rocket-chip/emulator/generated-src/unittest.AsyncQueueHalfResetConfig.fir -o /home/rocket-chip/emulator/generated-src/unittest.AsyncQueueHalfResetConfig.v -X verilog"

  cd /home/rocket-chip
  /tools/v4.210/bin/verilator \
    --cc --exe \
    --top-module TestHarness \
    --assert \
    --x-assign unique \
    -Wno-STMTDLY \
    -I/home/rocket-chip/vsrc \
    -Mdir /home/rocket-chip/emulator/generated-src/pr387_obj \
    -o /home/rocket-chip/emulator/generated-src/pr387_sim \
    /home/rocket-chip/emulator/generated-src/unittest.AsyncQueueHalfResetConfig.v \
    /home/rocket-chip/emulator/tb_main_pr387.cpp \
    -CFLAGS "-std=c++11 -O2"

  sed -i 's#VERILATOR_ROOT = /tools/verilator#VERILATOR_ROOT = /tools/v4.210/share/verilator#' \
    /home/rocket-chip/emulator/generated-src/pr387_obj/VTestHarness.mk

  make -C /home/rocket-chip/emulator/generated-src/pr387_obj -f VTestHarness.mk

  /home/rocket-chip/emulator/generated-src/pr387_sim +max-cycles=200
}

main() {
  mkdir -p "$WORK_DIR"

  echo "HWE_BENCH_RESULTS_START"

  if timeout 1200 bash -lc "$(declare -f prepare_sources); $(declare -f apply_register_router_compat); $(declare -f run_case_inner); run_case_inner" >"$RUN_LOG" 2>&1; then
    echo "TEST: $TEST_NAME ... PASS"
    echo "HWE_BENCH_RESULTS_END"
    exit 0
  fi

  rc=$?
  tail -n 80 "$RUN_LOG" || true
  echo "TEST: $TEST_NAME ... FAIL"
  echo "HWE_BENCH_RESULTS_END"
  exit 1
}

