#!/bin/bash

set -u
set -o pipefail

cd /home/rocket-chip || exit 1

export JAVA_HOME=/opt/jdk8
export PATH="$JAVA_HOME/bin:$PATH"

TEST_NAME="icache-reset-no-request"
SEEDS="1 2 3 4 5 6 7 8"
MAX_CYCLES=16
TARGET_DIR="/home/rocket-chip/.tbgen"
SCALA_FILE="/home/rocket-chip/src/main/scala/unittest/ICacheResetNoRequestUnitTest.scala"
HARNESS_FILE="$TARGET_DIR/icache_reset_harness.cpp"
FIRRTL_FILE="$TARGET_DIR/unittest.ICacheResetNoRequestUnitTestConfig.fir"
VERILOG_FILE="$TARGET_DIR/unittest.ICacheResetNoRequestUnitTestConfig.v"
SIM_DIR="$TARGET_DIR/obj_dir"
SIM_BIN="$TARGET_DIR/icache_reset_sim"
SBT_REPO_DIR="/home/rocket-chip/.sbt"
SBT_REPO_FILE="$SBT_REPO_DIR/repositories"

write_sbt_repositories() {
  mkdir -p "$SBT_REPO_DIR"
  cat > "$SBT_REPO_FILE" <<'EOF'
[repositories]
  local
  maven-central: https://repo1.maven.org/maven2/
  sbt-plugin-releases: https://repo.scala-sbt.org/scalasbt/sbt-plugin-releases/, [organization]/[module]/scala_[scalaVersion]/sbt_[sbtVersion]/[revision]/[type]s/[artifact](-[classifier]).[ext]
  typesafe-ivy-releases: https://repo.typesafe.com/typesafe/ivy-releases/, [organization]/[module]/[revision]/[type]s/[artifact](-[classifier]).[ext]
  typesafe-releases: https://repo.typesafe.com/typesafe/releases/
  sonatype-snapshots: https://oss.sonatype.org/content/repositories/snapshots
  typesafe-ivy-snapshots: https://repo.typesafe.com/typesafe/ivy-snapshots/, [organization]/[module]/[revision]/[type]s/[artifact](-[classifier]).[ext]
  jgit-repo: https://download.eclipse.org/jgit/maven/
EOF
}

run_sbt() {
  java \
    -Dsbt.log.noformat=true \
    -Dsbt.override.build.repos=true \
    -Dsbt.repository.config="$SBT_REPO_FILE" \
    -Dsbt.boot.directory="${SBT_BOOT_DIR:-/tools/sbt/boot}" \
    -Dsbt.ivy.home="${SBT_IVY_HOME:-/tools/sbt/ivy}" \
    -Xmx4G \
    -Xss8M \
    -jar /home/rocket-chip/sbt-launch.jar \
    "$@"
}

write_scala_test() {
  cat > "$SCALA_FILE" <<'EOF'
package unittest

import Chisel._
import cde.{CDEMatchError, Config, Parameters}
import rocket.{ICache, TileId}
import rocketchip.BaseConfig
import uncore.agents.CacheName
import uncore.tilelink.{Grant, TLId}

class ICacheResetNoRequestTest(implicit p: Parameters) extends UnitTest(timeout = 8) {
  val cacheParams = p.alterPartial {
    case CacheName => "L1I"
    case TLId => "L1toL2"
    case TileId => 0
  }
  val icache = Module(new ICache(2)(cacheParams))

  icache.io.req.valid := Bool(false)
  icache.io.req.bits.addr := UInt(0)
  icache.io.s1_ppn := UInt(0)
  icache.io.s1_kill := Bool(false)
  icache.io.s2_kill := Bool(false)
  icache.io.resp.ready := Bool(false)
  icache.io.invalidate := Bool(false)
  icache.io.mem.acquire.ready := Bool(false)
  icache.io.mem.grant.valid := Bool(false)
  icache.io.mem.grant.bits := Grant(
    is_builtin_type = Bool(true),
    g_type = Grant.getDataBeatType,
    client_xact_id = UInt(0),
    manager_xact_id = UInt(0),
    addr_beat = UInt(0),
    data = UInt(0))(cacheParams)

  val cycles = Reg(init = UInt(0, width = 3))
  cycles := cycles + UInt(1)
  io.finished := cycles === UInt(3)

  assert(!icache.io.resp.valid, "ICache emitted a response without a request after reset")
}

class WithICacheResetNoRequestUnitTest extends Config(
  (pname, site, here) => pname match {
    case rocketchip.NCoreplexExtClients => 0
    case UnitTests => (p: Parameters) => Seq(Module(new ICacheResetNoRequestTest()(p)))
    case _ => throw new CDEMatchError
  })

class ICacheResetNoRequestUnitTestConfig extends Config(
  new WithICacheResetNoRequestUnitTest ++ new BaseConfig)
EOF
}

write_harness() {
  cat > "$HARNESS_FILE" <<'EOF'
#include "VTestHarness.h"
#include "verilated.h"

#include <cstdlib>
#include <iostream>
#include <memory>
#include <string>

static vluint64_t main_time = 0;
double sc_time_stamp() { return main_time; }

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);
  Verilated::assertOn(true);

  int seed = 1;
  int max_cycles = 16;
  for (int i = 1; i < argc; ++i) {
    std::string arg = argv[i];
    if (arg.rfind("+seed=", 0) == 0) {
      seed = std::atoi(arg.c_str() + 6);
    } else if (arg.rfind("+max-cycles=", 0) == 0) {
      max_cycles = std::atoi(arg.c_str() + 12);
    }
  }

  std::srand(seed);
  srand48(seed);
  Verilated::randReset(2);

  std::unique_ptr<VTestHarness> top(new VTestHarness);

  top->clock = 1;
  top->reset = 1;
  for (int i = 0; i < 10; ++i) {
    top->clock = 0;
    top->eval();
    ++main_time;
    top->clock = 1;
    top->eval();
    ++main_time;
  }

  top->reset = 0;
  for (int cycle = 0; cycle < max_cycles; ++cycle) {
    top->clock = 0;
    top->eval();
    ++main_time;

    if (Verilated::gotFinish()) return 1;
    if (top->io_success) return 0;

    top->clock = 1;
    top->eval();
    ++main_time;

    if (Verilated::gotFinish()) return 1;
    if (top->io_success) return 0;
  }

  std::cerr << "timeout after " << max_cycles << " cycles" << std::endl;
  return 2;
}
EOF
}

run_reproducer() {
  rm -rf "$TARGET_DIR" &&
  mkdir -p /home/rocket-chip/src/main/scala/unittest &&
  mkdir -p "$TARGET_DIR" &&
  write_sbt_repositories &&
  write_scala_test &&
  write_harness &&
  run_sbt \
    "run-main unittest.Generator $TARGET_DIR unittest TestHarness unittest ICacheResetNoRequestUnitTestConfig" &&
  if [ ! -f firrtl/utils/bin/firrtl.jar ]; then
    (cd firrtl && run_sbt assembly)
  fi &&
  java -Xmx4G -Xss8M -cp firrtl/utils/bin/firrtl.jar firrtl.Driver \
    -i "$FIRRTL_FILE" \
    -o "$VERILOG_FILE" \
    -X verilog &&
  /tools/verilator/bin/verilator \
    --cc \
    --exe \
    --assert \
    -DRANDOMIZE_REG_INIT \
    -DRANDOMIZE_MEM_INIT \
    -O3 \
    -Wno-fatal \
    -Wno-STMTDLY \
    --top-module TestHarness \
    -Mdir "$SIM_DIR" \
    -o "$SIM_BIN" \
    "$VERILOG_FILE" \
    "$HARNESS_FILE" &&
  make -C "$SIM_DIR" -f VTestHarness.mk VERILATOR_ROOT=/tools/verilator/share/verilator &&
  for seed in $SEEDS; do
    if ! "$SIM_BIN" +seed="$seed" +max-cycles="$MAX_CYCLES"; then
      echo "seed $seed reproduced the reset-response bug" >&2
      return 1
    fi
  done
}

status=1
if run_reproducer; then
  status=0
fi

echo "HWE_BENCH_RESULTS_START"
if [ "$status" -eq 0 ]; then
  echo "TEST: $TEST_NAME ... PASS"
else
  echo "TEST: $TEST_NAME ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$status"

