#!/bin/bash
set -euo pipefail

export NUM_JOBS="${NUM_JOBS:-4}"
export MAKEFLAGS="-j${NUM_JOBS}"
export ROCKETCHIP_HOME=/home/rocket-chip
export COURSIER_CACHE="${COURSIER_CACHE:-/tools/coursier}"
export SBT_BOOT_DIR="${SBT_BOOT_DIR:-/tools/sbt/boot}"
