export SBT_IVY_HOME="${SBT_IVY_HOME:-/tools/sbt/ivy}"
export RISCV=/tools/riscv
export RISCV_HOME=/tools/riscv
export VERILATOR_ROOT=/tools/verilator
export JAVA_HOME=/opt/jdk8
export PATH="$JAVA_HOME/bin:/tools/bin:/tools/verilator/bin:/tools/riscv/bin:$PATH"

cd /home/rocket-chip
git reset --hard
git clean -fdx
git checkout 897b6863776329cccc5222acbe360a1dfc0a34cc
git submodule sync chisel3 firrtl hardfloat || true
git submodule update --init chisel3 firrtl hardfloat

cat > project/plugins.sbt <<'EOF'
addSbtPlugin("org.xerial.sbt" % "sbt-pack" % "0.8.0")
EOF

