#!/bin/bash
set -euo pipefail

cd /home/rocket-chip

if [[ -f /etc/rocket_chip_tools_path.sh ]]; then
  # shellcheck disable=SC1091
  source /etc/rocket_chip_tools_path.sh
fi

export JAVA_HOME="${JAVA_HOME:-/opt/jdk8}"
export RISCV="${RISCV:-/tools/riscv}"
export RISCV_HOME="${RISCV_HOME:-$RISCV}"
export VERILATOR_ROOT="${VERILATOR_ROOT:-/tools/verilator}"
export PATH="$JAVA_HOME/bin:$VERILATOR_ROOT/bin:$RISCV_HOME/bin:$PATH"
export ROCKETCHIP_ADDONS=".tb_pr1493/repro"

WORK=/home/rocket-chip/.tb_pr1493
REPRO_SRC="$WORK/repro/src/main/scala/repro"
SBT_REPOS="$WORK/sbt-repositories"
TB_MAIN="$WORK/tb_main.cpp"
GEN=/home/rocket-chip/emulator/generated-src
LONG=freechips.rocketchip.unittest.AsyncPBusBootROMUnitTestConfig
OBJ="$WORK/obj"
BIN="$WORK/sim"
TEST_NAME="async_pbus_bootrom_access"
TIME_LIMIT=1200
START_TIME=$(date +%s)
SBT_CMD="java -Dsbt.override.build.repos=true -Dsbt.repository.config=$SBT_REPOS -Xmx3G -Xss8M -XX:MaxPermSize=256M -jar /home/rocket-chip/sbt-launch.jar"

remaining_seconds() {
  echo $(( TIME_LIMIT - ($(date +%s) - START_TIME) ))
}

run_timed() {
  local remaining
  remaining=$(remaining_seconds)
  if (( remaining <= 0 )); then
    return 124
  fi
  timeout --foreground "${remaining}s" "$@"
}

write_reproducer_files() {
  mkdir -p "$REPRO_SRC" "$WORK"

  cat > "$SBT_REPOS" <<'EOF'
[repositories]
local
maven-central
sbt-plugin-releases: https://repo.scala-sbt.org/scalasbt/sbt-plugin-releases/, [organization]/[module]/(scala_[scalaVersion]/)(sbt_[sbtVersion]/)[revision]/[type]s/[artifact](-[classifier]).[ext]
typesafe-ivy-releases: https://repo.typesafe.com/typesafe/ivy-releases/, [organization]/[module]/(scala_[scalaVersion]/)(sbt_[sbtVersion]/)[revision]/[type]s/[artifact](-[classifier]).[ext]
sonatype-snapshots: https://oss.sonatype.org/content/repositories/snapshots
sonatype-releases: https://oss.sonatype.org/content/repositories/releases
jcenter: https://jcenter.bintray.com/
EOF

  cat > "$REPRO_SRC/AsyncPBusBootROM.scala" <<'EOF'
package freechips.rocketchip.repro

import Chisel._
import freechips.rocketchip.config.{Config, Parameters}
import freechips.rocketchip.devices.tilelink.HasPeripheryBootROM
import freechips.rocketchip.diplomacy.{AddressSet, LazyModule, LazyModuleImp}
import freechips.rocketchip.subsystem.{AsynchronousCrossing, BaseSubsystem, BaseSubsystemModuleImp, PeripheryBusKey, WithNMemoryChannels, WithNoMMIOPort, WithNoMemPort, WithNoSlavePort}
import freechips.rocketchip.system.BaseConfig
import freechips.rocketchip.tilelink.TLFuzzer
import freechips.rocketchip.unittest.{UnitTest, UnitTestModule, UnitTests}

class WithAsyncPeripheryBus extends Config((site, here, up) => {
  case PeripheryBusKey => up(PeripheryBusKey, site).copy(sbusCrossingType = AsynchronousCrossing(8, 3))
})

class AsyncPBusBootROMSubsystem(implicit p: Parameters) extends BaseSubsystem with HasPeripheryBootROM {
  override lazy val module = new AsyncPBusBootROMSubsystemModuleImp(this)
}

class AsyncPBusBootROMSubsystemModuleImp[+L <: AsyncPBusBootROMSubsystem](_outer: L)
    extends BaseSubsystemModuleImp(_outer) {
  val pbus_clock = IO(Clock(INPUT))
  val pbus_reset = IO(Bool(INPUT))

  outer.pbus.module.clock := pbus_clock
  outer.pbus.module.reset := pbus_reset
}

class AsyncPBusBootROMDUT(txns: Int)(implicit p: Parameters) extends LazyModule {
  private val bootromRange = AddressSet(0x10000, 0xffff)
  val fuzz = LazyModule(new TLFuzzer(txns, noModify = true, overrideAddress = Some(bootromRange)))
  val subsystem = LazyModule(new AsyncPBusBootROMSubsystem)

  subsystem.sbus.fromMaster(Some("fuzzer")) { fuzz.node }

  lazy val module = new AsyncPBusBootROMDUTModuleImp(this)
}

class AsyncPBusBootROMDUTModuleImp[+L <: AsyncPBusBootROMDUT](_outer: L)
    extends LazyModuleImp(_outer) with UnitTestModule {
  val outer = _outer
  outer.subsystem.module.pbus_clock := Bool(false).asClock
  outer.subsystem.module.pbus_reset := reset
  io.finished := outer.fuzz.module.io.finished
}

class AsyncPBusBootROMTest(txns: Int = 8, timeout: Int = 2000)(implicit p: Parameters) extends UnitTest(timeout) {
  val dut = Module(LazyModule(new AsyncPBusBootROMDUT(txns)).module)
  io.finished := dut.io.finished
}

class WithAsyncPBusBootROMUnitTest extends Config((site, here, up) => {
  case UnitTests => (q: Parameters) => {
    implicit val p = q
    Seq(Module(new AsyncPBusBootROMTest()))
  }
})

class AsyncPBusBootROMUnitTestConfig extends Config(
  new WithAsyncPBusBootROMUnitTest ++
  new WithAsyncPeripheryBus ++
  new WithNoMemPort ++
  new WithNoMMIOPort ++
  new WithNoSlavePort ++
  new WithNMemoryChannels(0) ++
  new BaseConfig)
EOF

  cat > "$TB_MAIN" <<'EOF'
#include "VTestHarness.h"
#include "verilated.h"
#include <cstdio>

static vluint64_t main_time = 0;
double sc_time_stamp() { return main_time; }

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);
  VTestHarness* top = new VTestHarness;
  top->clock = 0;
  top->reset = 1;
  const vluint64_t reset_cycles = 10;
  const vluint64_t timeout_cycles = 5000;

  while (!Verilated::gotFinish() && main_time < timeout_cycles) {
    if (main_time == reset_cycles) top->reset = 0;

    top->clock = 0;
    top->eval();
    if (Verilated::gotFinish()) break;

    top->clock = 1;
    top->eval();
    if (top->io_success) {
      delete top;
      return 0;
    }
    if (Verilated::gotFinish()) break;

    ++main_time;
  }

  if (main_time >= timeout_cycles) {
    std::fprintf(stderr, "Timed out after %llu cycles\n", static_cast<unsigned long long>(main_time));
  }

  delete top;
  return 1;
}
EOF
}

ensure_firrtl_available() {
  if [[ ! -f /root/.ivy2/local/edu.berkeley.cs/firrtl_2.11/1.2-SNAPSHOT/jars/firrtl_2.11.jar ]]; then
    pushd /home/rocket-chip/firrtl >/dev/null
    run_timed bash -lc "$SBT_CMD publishLocal"
    local rc=$?
    popd >/dev/null
    (( rc == 0 )) || return "$rc"
  fi
}

run_reproducer() {
  rm -f \
    "$GEN/$LONG.fir" \
    "$GEN/$LONG.d" \
    "$GEN/$LONG.v" \
    "$GEN/$LONG.conf" \
    "$GEN/$LONG.anno.json" \
    "$GEN/$LONG.behav_srams.v" \
    "$GEN/$LONG.behav_srams.v.tmp"
  rm -rf "$GEN/$LONG" "$OBJ" "$BIN"
  mkdir -p "$GEN"

  rm -f \
    /home/rocket-chip/lib/firrtl.jar \
    /home/rocket-chip/chisel3/lib/firrtl.jar \
    /home/rocket-chip/firrtl/utils/bin/firrtl.jar

  pushd /home/rocket-chip >/dev/null
  run_timed bash -lc "$SBT_CMD \"runMain freechips.rocketchip.unittest.Generator $GEN freechips.rocketchip.unittest TestHarness freechips.rocketchip.repro AsyncPBusBootROMUnitTestConfig\""
  local rc=$?
  popd >/dev/null
  (( rc == 0 )) || return "$rc"

  pushd /home/rocket-chip >/dev/null
  run_timed bash -lc "$SBT_CMD \"runMain firrtl.Driver -i $GEN/$LONG.fir -o $GEN/$LONG.v -X verilog --infer-rw TestHarness --repl-seq-mem -c:TestHarness:-o:$GEN/$LONG.conf -faf $GEN/$LONG.anno.json -td $GEN/$LONG\""
  rc=$?
  popd >/dev/null
  (( rc == 0 )) || return "$rc"

  run_timed bash -lc "cd $GEN && /home/rocket-chip/scripts/vlsi_mem_gen $GEN/$LONG.conf > $GEN/$LONG.behav_srams.v.tmp && mv -f $GEN/$LONG.behav_srams.v.tmp $GEN/$LONG.behav_srams.v" || return $?

  run_timed "$VERILATOR_ROOT/bin/verilator" --cc --exe --assert \
    --top-module TestHarness \
    -Wno-STMTDLY \
    --x-assign unique \
    -O3 \
    -I/home/rocket-chip/src/main/resources/vsrc \
    -Mdir "$OBJ" \
    -o "$BIN" \
    "$GEN/$LONG.v" \
    "$GEN/$LONG.behav_srams.v" \
    /home/rocket-chip/src/main/resources/vsrc/AsyncResetReg.v \
    /home/rocket-chip/src/main/resources/vsrc/ClockDivider2.v \
    /home/rocket-chip/src/main/resources/vsrc/ClockDivider3.v \
    /home/rocket-chip/src/main/resources/vsrc/plusarg_reader.v \
    "$TB_MAIN" || return $?

  run_timed make -C "$OBJ" -f VTestHarness.mk || return $?
  run_timed "$BIN"
}

echo "HWE_BENCH_RESULTS_START"

status=0
write_reproducer_files || status=$?
if (( status == 0 )); then
  ensure_firrtl_available || status=$?
fi
if (( status == 0 )); then
  run_reproducer || status=$?
fi

if (( status == 0 )); then
  echo "TEST: $TEST_NAME ... PASS"
  echo "HWE_BENCH_RESULTS_END"
  exit 0
fi

echo "TEST: $TEST_NAME ... FAIL"
echo "HWE_BENCH_RESULTS_END"
exit 1

