case object HWEBenchUserBits extends UserBits {
  val width = 8
}

class HWEBenchTLSource(txns: Int)(implicit p: Parameters) extends LazyModule {
  val node = TLClientNode(Seq(TLClientPortParameters(Seq(TLClientParameters(
    name = "HWEBenchTLSource",
    sourceId = IdRange(0, txns))))))

  lazy val module = new LazyModuleImp(this) {
    val io = IO(new Bundle {
      val finished = Bool(OUTPUT)
    })

    val (out, edge) = node.out(0)
    val sent = RegInit(UInt(0, width = log2Ceil(txns + 1)))
    val recv = RegInit(UInt(0, width = log2Ceil(txns + 1)))

    val done = sent === UInt(txns)
    val addr = Cat(UInt(0, width = 6), sent, UInt(0, width = 2))(7, 0)
    val data = Cat(UInt(0x55, width = 24), addr)
    val (legal, bits) = edge.Put(sent, addr, UInt(2), data)

    assert(legal)

    out.a.valid := !done
    out.a.bits := bits
    out.d.ready := Bool(true)
    out.b.ready := Bool(true)
    out.c.valid := Bool(false)
    out.e.valid := Bool(false)

    when (out.a.fire()) {
      sent := sent + UInt(1)
    }
    when (out.d.fire()) {
      recv := recv + UInt(1)
    }

    io.finished := recv === UInt(txns)
  }
}

class HWEBenchAHBSink(implicit p: Parameters) extends LazyModule {
  val node = AHBSlaveSinkNode(Seq(AHBSlavePortParameters(
    slaves = Seq(AHBSlaveParameters(
      address       = Seq(AddressSet(0x0, 0xff)),
      executable    = false,
      supportsRead  = TransferSizes(1, 4),
      supportsWrite = TransferSizes(1, 4))),
    beatBytes = 4)))

  lazy val module = new LazyModuleImp(this) {
    val (in, _) = node.in(0)
    val a_access = in.htrans === AHBParameters.TRANS_NONSEQ || in.htrans === AHBParameters.TRANS_SEQ
    val a_request = in.hready && in.hsel && a_access
    val stall = RegInit(Bool(false))

    when (stall) {
      stall := Bool(false)
    } .elsewhen (a_request) {
      stall := Bool(true)
    }

    in.hreadyout := !stall
    in.hresp := AHBParameters.RESP_OKAY
    in.hrdata := UInt(0)

    when (a_request) {
      assert(in.hauser.get === in.haddr(7, 0), "hauser must stay aligned with haddr")
    }
  }
}

class HWEBenchUserBitsSyncDUT(aFlow: Boolean, txns: Int)(implicit p: Parameters) extends LazyModule {
  val source = LazyModule(new HWEBenchTLSource(txns))
  val sink = LazyModule(new HWEBenchAHBSink)
  val arb = LazyModule(new AHBArbiter)

  sink.node := arb.node := TLToAHB(aFlow) := TLUserUser(HWEBenchUserBits, { case (a, _) => a.address(7, 0) }) := source.node

  lazy val module = new LazyModuleImp(this) with UnitTestModule {
    io.finished := source.module.io.finished
  }
}

class HWEBenchUserBitsSyncTest(aFlow: Boolean, txns: Int = 4, timeout: Int = 20000)(implicit p: Parameters) extends UnitTest(timeout) {
  val dut = Module(LazyModule(new HWEBenchUserBitsSyncDUT(aFlow, txns)).module)
  io.finished := dut.io.finished
  dut.io.start := Bool(true)
}
EOF

