  jtag_cycle(&top, 1); // RunTestIdle -> SelectDRScan
  jtag_cycle(&top, 0); // SelectDRScan -> CaptureDR
  jtag_cycle(&top, 0); // CaptureDR -> ShiftDR, then negedge latches TDO/TDO.driven

  if (!(top.io_jtag_TDO_data == 1 && top.io_jtag_TDO_driven == 1)) {
    VL_PRINTF("failed to drive TDO before reset: data=%d driven=%d\n",
              (int)top.io_jtag_TDO_data, (int)top.io_jtag_TDO_driven);
    return 2;
  }

  top.io_control_jtag_reset = 1;
  eval(&top);

  if (top.io_jtag_TDO_data == 0 && top.io_jtag_TDO_driven == 0) {
    VL_PRINTF("PASS async reset cleared TDO outputs immediately\n");
    return 0;
  }

  VL_PRINTF("FAIL async reset did not clear TDO outputs immediately: data=%d driven=%d\n",
            (int)top.io_jtag_TDO_data, (int)top.io_jtag_TDO_driven);
  return 1;
}
EOF

