#!/bin/bash

set -uo pipefail

cd /home/rocket-chip || exit 1

export JAVA_HOME=/opt/jdk8
export PATH="$JAVA_HOME/bin:$PATH"
export RISCV_HOME=/tools/riscv
export RISCV=/tools/riscv

probe_src=/home/rocket-chip/src/main/scala/amba/apb/HWEAPBFanoutBehaviorProbe.scala

cat > "$probe_src" <<'EOF'
package freechips.rocketchip.amba.apb

import Chisel._
import chisel3.testers.{BasicTester, TesterDriver}
import freechips.rocketchip.config.Parameters
import freechips.rocketchip.devices.debug.DebugModuleKey
import freechips.rocketchip.diplomacy._
import freechips.rocketchip.system.{DefaultConfig, ExampleRocketSystem, WithDebugAPB}

class HWEAPBProbeMaster()(implicit p: Parameters) extends LazyModule {
  val node = APBMasterNode(Seq(APBMasterPortParameters(Seq(APBMasterParameters("HWEAPBProbeMaster")))))

  lazy val module = new LazyModuleImp(this) {
    val (out, edge) = node.out(0)
    val io = IO(new Bundle {
      val psel    = Bool(INPUT)
      val penable = Bool(INPUT)
      val pwrite  = Bool(INPUT)
      val paddr   = UInt(INPUT, width = edge.bundle.addrBits)
      val pwdata  = UInt(INPUT, width = edge.bundle.dataBits)
      val pstrb   = UInt(INPUT, width = edge.bundle.dataBits/8)
      val pready  = Bool(OUTPUT)
      val pslverr = Bool(OUTPUT)
      val prdata  = UInt(OUTPUT, width = edge.bundle.dataBits)
    })

    out.psel    := io.psel
    out.penable := io.penable
    out.pwrite  := io.pwrite
    out.paddr   := io.paddr
    out.pprot   := APBParameters.PROT_DEFAULT
    out.pwdata  := io.pwdata
    out.pstrb   := io.pstrb
    out.pauser.foreach { _ := UInt(0) }

    io.pready  := out.pready
    io.pslverr := out.pslverr
    io.prdata  := out.prdata
  }
}

class HWEAPBProbeSlave(address: Seq[AddressSet], readData: BigInt)(implicit p: Parameters) extends LazyModule {
  val node = APBSlaveNode(Seq(APBSlavePortParameters(
    Seq(APBSlaveParameters(
      address = address,
      supportsWrite = true,
      supportsRead = true)),
    beatBytes = 4)))

  lazy val module = new LazyModuleImp(this) {
    val (in, edge) = node.in(0)
    val io = IO(new Bundle {
      val psel    = Bool(OUTPUT)
      val penable = Bool(OUTPUT)
    })

    io.psel    := in.psel
    io.penable := in.penable

    in.pready  := Bool(true)
    in.pslverr := Bool(false)
    in.prdata  := UInt(readData, width = edge.bundle.dataBits)
  }
}

class HWEAPBFanoutProbe(dmiTop: Int, apbRegBase: Int, includeGapResponder: Boolean)(implicit p: Parameters)
    extends LazyModule {
  val master = LazyModule(new HWEAPBProbeMaster())
  val fanout = LazyModule(new APBFanout)
  val dmiRegs = LazyModule(new HWEAPBProbeSlave(Seq(AddressSet(0, dmiTop - 1)), 0x11))
  val gapResponder = if (includeGapResponder) {
    Some(LazyModule(new HWEAPBProbeSlave(AddressSet.misaligned(dmiTop, apbRegBase - dmiTop), 0x33)))
  } else {
    None
  }
  val apbRegs = LazyModule(new HWEAPBProbeSlave(Seq(AddressSet(apbRegBase, 0xff)), 0x22))

  dmiRegs.node := fanout.node
  gapResponder.foreach { _.node := fanout.node }
  apbRegs.node := fanout.node
  fanout.node  := master.node

  lazy val module = new LazyModuleImp(this) {
    val io = IO(new Bundle {
      val psel     = Bool(INPUT)
      val penable  = Bool(INPUT)
      val paddr    = UInt(INPUT, width = master.module.io.paddr.getWidth)
      val dmiPsel  = Bool(OUTPUT)
      val dmiPen   = Bool(OUTPUT)
      val gapPsel  = Bool(OUTPUT)
      val gapPen   = Bool(OUTPUT)
      val apbPsel  = Bool(OUTPUT)
      val apbPen   = Bool(OUTPUT)
      val prdata   = UInt(OUTPUT, width = master.module.io.prdata.getWidth)
    })

    master.module.io.psel    := io.psel
    master.module.io.penable := io.penable
    master.module.io.pwrite  := Bool(false)
    master.module.io.paddr   := io.paddr
    master.module.io.pwdata  := UInt(0)
    master.module.io.pstrb   := UInt(0xf)

    io.dmiPsel := dmiRegs.module.io.psel
    io.dmiPen  := dmiRegs.module.io.penable
    io.gapPsel := gapResponder.map(_.module.io.psel).getOrElse(Bool(false))
    io.gapPen  := gapResponder.map(_.module.io.penable).getOrElse(Bool(false))
    io.apbPsel := apbRegs.module.io.psel
    io.apbPen  := apbRegs.module.io.penable
    io.prdata  := master.module.io.prdata
  }
}

class HWEAPBFanoutBehaviorTester(dmiTop: Int, apbRegBase: Int, includeGapResponder: Boolean)(implicit p: Parameters)
    extends BasicTester {
  val dut = Module(LazyModule(new HWEAPBFanoutProbe(dmiTop, apbRegBase, includeGapResponder)).module)
  val cycle = Reg(init = UInt(0, width = 4))
  cycle := cycle + UInt(1)

  val gapAddr = UInt(dmiTop, width = dut.io.paddr.getWidth)
  val dmiAddr = UInt(dmiTop - 4, width = dut.io.paddr.getWidth)
  val apbAddr = UInt(apbRegBase, width = dut.io.paddr.getWidth)

  dut.io.psel := cycle >= UInt(1) && cycle <= UInt(6)
  dut.io.penable := cycle === UInt(2) || cycle === UInt(4) || cycle === UInt(6)
  dut.io.paddr := Mux(cycle <= UInt(2), gapAddr, Mux(cycle <= UInt(4), dmiAddr, apbAddr))

  when (cycle === UInt(1) || cycle === UInt(2)) {
    assert(!dut.io.dmiPsel, "gap address selected the DMI-backed APB target")
    assert(!dut.io.apbPsel, "gap address selected the APB debug register target")
    assert(!dut.io.dmiPen, "gap access phase enabled the DMI-backed APB target")
    assert(!dut.io.apbPen, "gap access phase enabled the APB debug register target")
    if (includeGapResponder) {
      assert(dut.io.gapPsel, "explicit gap responder was not selected")
      when (cycle === UInt(2)) {
        assert(dut.io.gapPen, "explicit gap responder was not enabled in access phase")
      }
    } else {
      assert(!dut.io.gapPsel, "gap responder unexpectedly exists")
      assert(!dut.io.gapPen, "gap responder unexpectedly exists in access phase")
    }
  }

  when (cycle === UInt(3) || cycle === UInt(4)) {
    assert(dut.io.dmiPsel, "valid DMI-backed APB address did not select DMI target")
    assert(!dut.io.gapPsel, "valid DMI-backed APB address selected gap responder")
    assert(!dut.io.apbPsel, "valid DMI-backed APB address selected APB debug registers")
    assert(dut.io.prdata === UInt(0x11), "valid DMI-backed APB address returned wrong read data")
  }

  when (cycle === UInt(5) || cycle === UInt(6)) {
    assert(!dut.io.dmiPsel, "valid APB debug register address selected DMI target")
    assert(!dut.io.gapPsel, "valid APB debug register address selected gap responder")
    assert(dut.io.apbPsel, "valid APB debug register address did not select APB debug target")
    assert(dut.io.prdata === UInt(0x22), "valid APB debug register address returned wrong read data")
  }

  when (cycle === UInt(7)) { stop() }
}

object HWEAPBFanoutBehaviorProbe extends App {
  implicit val p: Parameters = new WithDebugAPB ++ new DefaultConfig

  val system = LazyModule(new ExampleRocketSystem)
  val debug = system.debugOpt.getOrElse {
    throw new RuntimeException("debug module was not instantiated")
  }
  val apbNode = debug.apbNodeOpt.getOrElse {
    throw new RuntimeException("APB debug interface was not instantiated")
  }

  val cfg = p(DebugModuleKey).get
  val dmiTop = (1 << cfg.nDMIAddrSize) << 2
  val apbPorts = apbNode.edges.out.map(_.slave.slaves.flatMap(_.address))
  if (apbPorts.size < 2) {
    throw new RuntimeException(s"expected APB fanout to have at least 2 outputs, got ${apbPorts.size}")
  }

  val apbRegBase = apbPorts.flatten.map(_.base).max.toInt
  if (dmiTop >= apbRegBase) {
    throw new RuntimeException(
      s"expected a debug APB gap, got dmiTop=0x${dmiTop.toHexString}, apbRegBase=0x${apbRegBase.toHexString}")
  }

  def owners(addr: Int): Seq[Int] =
    apbPorts.zipWithIndex.collect { case (sets, idx) if sets.exists(_.contains(BigInt(addr))) => idx }

  val gapAddrs = dmiTop until apbRegBase by 4
  val includeGapResponder = gapAddrs.nonEmpty && gapAddrs.forall(addr => owners(addr).nonEmpty)

  println(
    s"debug APB behavioral probe: dmiTop=0x${dmiTop.toHexString}, apbRegBase=0x${apbRegBase.toHexString}, explicitGapResponder=$includeGapResponder")

  val ok = TesterDriver.execute(() => new HWEAPBFanoutBehaviorTester(dmiTop, apbRegBase, includeGapResponder))
  if (!ok) {
    throw new RuntimeException("APBFanout boundary behavior does not protect the debug APB gap")
  }
}
EOF

echo "HWE_BENCH_RESULTS_START"
timeout 1200s sbt -no-colors "runMain freechips.rocketchip.amba.apb.HWEAPBFanoutBehaviorProbe"
status=$?

if [ "$status" -eq 0 ]; then
  echo "TEST: debug_apb_gap_behavior ... PASS"
else
  echo "TEST: debug_apb_gap_behavior ... FAIL"
fi
echo "HWE_BENCH_RESULTS_END"

exit "$status"

#!/bin/bash
set -u

cd /home/rocket-chip || exit 1

TEST_NAME="frontend_progress_quiesce"
WORKDIR="/home/rocket-chip/.hwe-bench-pr3004"
SCALA_FILE="src/main/scala/unittest/FrontendProgressUnitTest.scala"
RUNNER_FILE="frontend_progress_runner.cpp"
BUILD_DIR="frontend-progress-build"
OBJ_DIR="frontend-progress-obj"

write_sources() {
  cat > "$SCALA_FILE" <<'EOF'
package freechips.rocketchip.unittest

import Chisel._
import freechips.rocketchip.config.{Config, Parameters}
import freechips.rocketchip.diplomacy.{AddressSet, BundleBridgeSource, LazyModule, LazyModuleImp, ValName}
import freechips.rocketchip.prci.ClockSinkParameters
import freechips.rocketchip.rocket._
import freechips.rocketchip.system.DefaultConfig
import freechips.rocketchip.tile._
import freechips.rocketchip.tilelink._

case class FrontendProgressTileParams(
  core: RocketCoreParams = RocketCoreParams(
    useHypervisor = true,
    useCompressed = false,
    useAtomics = false,
    useDebug = false,
    fpu = None,
    nPMPs = 0),
  icache: Option[ICacheParams] = Some(ICacheParams(
    nTLBSets = 1,
    nTLBWays = 1,
    nTLBBasePageSectors = 1,
    nTLBSuperpages = 1)),
  dcache: Option[DCacheParams] = Some(DCacheParams()),
  btb: Option[BTBParams] = None,
  hartId: Int = 0,
  beuAddr: Option[BigInt] = None,
  blockerCtrlAddr: Option[BigInt] = None,
  name: Option[String] = Some("frontend-progress-test"),
  clockSinkParams: ClockSinkParameters = ClockSinkParameters()
) extends TileParams

class FrontendProgressHarness private (
  private val tileParams: FrontendProgressTileParams,
  private val visibilityNode: TLEphemeralNode
)(implicit p: Parameters) extends LazyModule()(p) {
  private val resetVectorSource = BundleBridgeSource[UInt]()
  private val xbar = LazyModule(new TLXbar)
  private val ram = LazyModule(new TLRAM(AddressSet(0x0, 0x1ffff), beatBytes = 4))
  private val frontend = LazyModule(new Frontend(tileParams.icache.get, 0))

  ram.node := TLFragmenter(4, 64) := xbar.node
  xbar.node := visibilityNode := frontend.masterNode
  frontend.resetVectorSinkNode := resetVectorSource

  lazy val module = new LazyModuleImp(this) with UnitTestModule {
    resetVectorSource.bundle := 0.U

    val dut = frontend.module
    val started = RegInit(false.B)
    when (io.start) { started := true.B }

    val sIdle :: sIssue :: sWaitReq :: sGap :: sDone :: Nil = Enum(UInt(), 5)
    val state = RegInit(sIdle)
    val requestIdx = RegInit(0.U(3.W))
    val gapCycles = RegInit(0.U(3.W))
    val quiesce = RegInit(false.B)
    val quiesceCycles = RegInit(0.U(6.W))
    val watchdog = RegInit(0.U(8.W))

    when (started && state =/= sDone) { watchdog := watchdog + 1.U }
    assert(watchdog =/= 250.U, "Frontend progress test timed out")

    val issueReq = started && state === sIssue
    val requestPc = (requestIdx + 1.U) << 12

    dut.io.cpu.might_request := started
    dut.io.cpu.req.valid := issueReq
    dut.io.cpu.req.bits.pc := requestPc
    dut.io.cpu.req.bits.speculative := true.B
    dut.io.cpu.sfence.valid := false.B
    dut.io.cpu.sfence.bits := 0.U.asTypeOf(dut.io.cpu.sfence.bits)
    dut.io.cpu.resp.ready := true.B
    dut.io.cpu.btb_update.valid := false.B
    dut.io.cpu.btb_update.bits := 0.U.asTypeOf(dut.io.cpu.btb_update.bits)
    dut.io.cpu.bht_update.valid := false.B
    dut.io.cpu.bht_update.bits := 0.U.asTypeOf(dut.io.cpu.bht_update.bits)
    dut.io.cpu.ras_update.valid := false.B
    dut.io.cpu.ras_update.bits := 0.U.asTypeOf(dut.io.cpu.ras_update.bits)
    dut.io.cpu.flush_icache := false.B
    dut.io.cpu.elements.get("progress").foreach { _.asUInt := 0.U }

    val ptwRespPte = Wire(new PTE)
    ptwRespPte := 0.U.asTypeOf(new PTE)
    ptwRespPte.v := true.B
    ptwRespPte.r := true.B
    ptwRespPte.w := true.B
    ptwRespPte.x := true.B
    ptwRespPte.a := true.B
    ptwRespPte.d := true.B
    ptwRespPte.ppn := (requestIdx + 1.U).pad(ptwRespPte.ppn.getWidth)

    val realPtwReq = dut.io.ptw.req.fire() && dut.io.ptw.req.bits.valid
    val sendResp = RegNext(realPtwReq, false.B)
    val replayResp = dut.io.cpu.resp.fire() && dut.io.cpu.resp.bits.replay

    when (!quiesce && replayResp && requestIdx >= 2.U) {
      quiesce := true.B
      quiesceCycles := 0.U
    }

    when (quiesce) {
      quiesceCycles := quiesceCycles + 1.U
      assert(!realPtwReq, "Frontend sent another speculative PTW request after replay started")
      when (quiesceCycles === 20.U) { state := sDone }
    }

    dut.io.ptw.req.ready := true.B
    dut.io.ptw.resp.valid := sendResp
    dut.io.ptw.resp.bits := 0.U.asTypeOf(dut.io.ptw.resp.bits)
    dut.io.ptw.resp.bits.hx := true.B
    dut.io.ptw.resp.bits.hr := true.B
    dut.io.ptw.resp.bits.hw := true.B
    dut.io.ptw.resp.bits.pte := ptwRespPte
    dut.io.ptw.resp.bits.level := 2.U
    dut.io.ptw.resp.bits.homogeneous := true.B
    dut.io.ptw.resp.bits.gpa.valid := false.B
    dut.io.ptw.resp.bits.gpa.bits := 0.U
    dut.io.ptw.resp.bits.gpa_is_pte := false.B

    dut.io.ptw.ptbr := 0.U.asTypeOf(dut.io.ptw.ptbr)
    dut.io.ptw.ptbr.mode := 8.U
    dut.io.ptw.hgatp := 0.U.asTypeOf(dut.io.ptw.hgatp)
    dut.io.ptw.hgatp.mode := 8.U
    dut.io.ptw.vsatp := 0.U.asTypeOf(dut.io.ptw.vsatp)
    dut.io.ptw.vsatp.mode := 8.U
    dut.io.ptw.status := 0.U.asTypeOf(dut.io.ptw.status)
    dut.io.ptw.status.prv := PRV.S.U
    dut.io.ptw.status.v := true.B
    dut.io.ptw.hstatus := 0.U.asTypeOf(dut.io.ptw.hstatus)
    dut.io.ptw.gstatus := 0.U.asTypeOf(dut.io.ptw.gstatus)
    dut.io.ptw.customCSRs := 0.U.asTypeOf(dut.io.ptw.customCSRs)
    dut.io.ptw.pmp.foreach { _ := 0.U.asTypeOf(new PMP) }

    switch (state) {
      is (sIdle) {
        when (started) { state := sIssue }
      }
      is (sIssue) {
        state := sWaitReq
      }
      is (sWaitReq) {
        when (realPtwReq) {
          requestIdx := requestIdx + 1.U
          gapCycles := 0.U
          state := sGap
        }
      }
      is (sGap) {
        gapCycles := gapCycles + 1.U
        when (gapCycles === 3.U) { state := sIssue }
      }
    }

    io.finished := state === sDone
  }
}

object FrontendProgressHarness {
  def apply(): FrontendProgressHarness = {
    val tileParams = FrontendProgressTileParams()
    val visibilityNode = TLEphemeralNode()(ValName("frontend_progress_visibility"))
    implicit val p: Parameters = (new DefaultConfig).alterMap(Map(
      TileKey -> tileParams,
      TileVisibilityNodeKey -> visibilityNode,
      LookupByHartId -> HartsWontDeduplicate(tileParams)))
    implicit val valName: ValName = ValName("frontend_progress_harness")
    LazyModule(new FrontendProgressHarness(tileParams, visibilityNode))
  }
}

class FrontendProgressTest(timeout: Int = 5000)(implicit p: Parameters) extends UnitTest(timeout) {
  val dut = Module(FrontendProgressHarness().module)
  dut.io.start := io.start
  io.finished := dut.io.finished
}

class FrontendProgressUnitTestConfig extends Config((site, here, up) => {
  case UnitTests => (q: Parameters) => {
    implicit val p: Parameters = q
    Seq(Module(new FrontendProgressTest))
  }
})
EOF

  cat > "$RUNNER_FILE" <<'EOF'
#include "VTestHarness.h"
#include "verilated.h"

#include <cstdint>
#include <cstdio>

static void step(VTestHarness& top, bool reset) {
  top.reset = reset;
  top.clock = 0;
  top.eval();
  top.clock = 1;
  top.eval();
}

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);
  VTestHarness top;

  step(top, true);
  step(top, false);
  step(top, true);
  for (int i = 0; i < 10; ++i) {
    step(top, true);
  }

  const std::uint64_t max_cycles = 2000;
  for (std::uint64_t cycle = 0; cycle < max_cycles; ++cycle) {
    if (Verilated::gotFinish()) {
      std::fprintf(stderr, "simulation finished early at cycle %llu\n",
        static_cast<unsigned long long>(cycle));
      return 1;
    }
    if (top.io_success) {
      return 0;
    }
    step(top, false);
  }

  std::fprintf(stderr, "timeout waiting for io_success\n");
  return 2;
}
EOF
}

