package freechips.rocketchip.rocket

import chisel3._
import chisel3.util._
import _root_.circt.stage.ChiselStage
import org.chipsalliance.cde.config.Parameters
import freechips.rocketchip.diplomacy._
import freechips.rocketchip.subsystem.BaseSubsystemConfig
import freechips.rocketchip.subsystem.CacheBlockBytes
import freechips.rocketchip.subsystem.SystemBusKey
import freechips.rocketchip.subsystem.WithHypervisor
import freechips.rocketchip.tile._
import freechips.rocketchip.tilelink._

class PTWStage2CacheHarnessLazy(baseParams: Parameters) extends LazyModule()(baseParams.alterMap(Map(
  TileKey -> RocketTileParams(
    core = RocketCoreParams(useHypervisor = true),
    icache = Some(ICacheParams(
      rowBits = baseParams(SystemBusKey).beatBits,
      blockBytes = baseParams(CacheBlockBytes))),
    dcache = Some(DCacheParams(
      rowBits = baseParams(SystemBusKey).beatBits,
      nMSHRs = 0,
      blockBytes = baseParams(CacheBlockBytes))),
    hartId = 0),
  TileVisibilityNodeKey -> TLEphemeralNode()(ValName("ptw_stage2_cache_tile"))
))) {
  private val visibilityNode = p(TileVisibilityNodeKey)
  private val edgeClient = TLClientNode(Seq(TLMasterPortParameters.v1(
    clients = Seq(TLMasterParameters.v1(name = "ptw-stage2-cache", sourceId = IdRange(0, 1))),
    minLatency = 1)))
  private val masterNode: TLOutwardNode = TLIdentityNode() := visibilityNode := edgeClient
  private val edgeRam = LazyModule(new TLRAM(AddressSet(0x0, 0xffffff), beatBytes = baseParams(CacheBlockBytes)))
  edgeRam.node := masterNode

  lazy val module = new Impl

  class Impl extends LazyModuleImp(this) {
    override def desiredName = "PTWStage2CacheHarnessInner"

    val io = IO(new Bundle {
      val success = Output(Bool())
    })

    implicit val edge = visibilityNode.edges.out.head
    val ptw = Module(new PTW(1))

    val requestVpn = "h00040123".U(ptw.io.requestor(0).req.bits.bits.addr.getWidth.W)
    val vsatpPpn = "h000123".U(ptw.io.dpath.vsatp.ppn.getWidth.W)
    val hgatpPpn = "h000400".U(ptw.io.dpath.hgatp.ppn.getWidth.W)
    val guestNextPpn = "h08000456".U(ptw.io.dpath.vsatp.ppn.getWidth.W)
    val hostStage2L1Ppn = "h000500".U(ptw.io.requestor(0).resp.bits.pte.ppn.getWidth.W)
    val hostStage2L2Ppn = "h000580".U(ptw.io.requestor(0).resp.bits.pte.ppn.getWidth.W)
    val hostStage2LeafPpn = "h000600".U(ptw.io.requestor(0).resp.bits.pte.ppn.getWidth.W)

    def ptbr(mode: UInt, ppn: UInt): PTBR = {
      val out = Wire(new PTBR)
      out := 0.U.asTypeOf(new PTBR)
      out.mode := mode
      out.ppn := ppn
      out
    }

    def leafPte(ppn: UInt): UInt = {
      val pte = Wire(new PTE)
      pte := 0.U.asTypeOf(new PTE)
      pte.ppn := ppn
      pte.d := true.B
      pte.a := true.B
      pte.u := true.B
      pte.w := true.B
      pte.r := true.B
      pte.v := true.B
      pte.asUInt
    }

    def tablePte(ppn: UInt): UInt = {
      val pte = Wire(new PTE)
      pte := 0.U.asTypeOf(new PTE)
      pte.ppn := ppn
      pte.v := true.B
      pte.asUInt
    }

    def hypervisorRootPpn(hgatp: UInt, vpn: UInt): UInt = {
      val root = Wire(UInt(ptw.io.dpath.hgatp.ppn.getWidth.W))
      root := Cat(hgatp >> 2, (vpn >> 27)(1, 0))
      root
    }

    def stage2RootAddr(rootPpn: UInt, vpn: UInt): UInt = {
      ((((rootPpn << 9) | ((vpn >> 18) & "h7ff".U)) << 3))(ptw.io.mem.req.bits.addr.getWidth - 1, 0)
    }

    val expectedWrongRootPpn = hypervisorRootPpn(hgatpPpn, vsatpPpn)
    val expectedCorrectRootPpn = hypervisorRootPpn(hgatpPpn, guestNextPpn)

    ptw.io.dpath.ptbr := ptbr(0.U, 0.U)
    ptw.io.dpath.hgatp := ptbr(8.U, hgatpPpn)
    ptw.io.dpath.vsatp := ptbr(8.U, vsatpPpn)
    ptw.io.dpath.sfence.valid := false.B
    ptw.io.dpath.sfence.bits := 0.U.asTypeOf(ptw.io.dpath.sfence.bits)
    ptw.io.dpath.status := 0.U.asTypeOf(new MStatus)
    ptw.io.dpath.hstatus := 0.U.asTypeOf(new HStatus)
    ptw.io.dpath.gstatus := 0.U.asTypeOf(new MStatus)
    ptw.io.dpath.pmp.foreach(_ := 0.U.asTypeOf(new PMP))
    val dummyCustomCSRs = Wire(chiselTypeOf(ptw.io.dpath.customCSRs))
    dummyCustomCSRs := DontCare
    ptw.io.dpath.customCSRs <> dummyCustomCSRs

    ptw.io.requestor(0).req.bits.valid := true.B
    ptw.io.requestor(0).req.bits.bits.addr := requestVpn
    ptw.io.requestor(0).req.bits.bits.need_gpa := false.B
    ptw.io.requestor(0).req.bits.bits.vstage1 := true.B
    ptw.io.requestor(0).req.bits.bits.stage2 := true.B
    val dummyReqCustomCSRs = Wire(chiselTypeOf(ptw.io.requestor(0).customCSRs))
    dummyReqCustomCSRs := DontCare
    ptw.io.requestor(0).customCSRs <> dummyReqCustomCSRs
    ptw.io.mem.req.ready := true.B
    ptw.io.mem.s2_nack := false.B
    ptw.io.mem.s2_nack_cause_raw := false.B
    ptw.io.mem.s2_uncached := false.B
    ptw.io.mem.s2_paddr := 0.U
    ptw.io.mem.replay_next := false.B
    ptw.io.mem.s2_xcpt := 0.U.asTypeOf(new HellaCacheExceptions)
    ptw.io.mem.s2_gpa := 0.U
    ptw.io.mem.s2_gpa_is_pte := false.B
    ptw.io.mem.ordered := false.B
    ptw.io.mem.perf := 0.U.asTypeOf(new HellaCachePerfEvents)
    ptw.io.mem.clock_enabled := true.B
    ptw.io.mem.resp.valid := false.B
    ptw.io.mem.resp.bits := 0.U.asTypeOf(new HellaCacheResp)
    ptw.io.mem.uncached_resp.foreach { resp =>
      resp.valid := false.B
      resp.bits := 0.U.asTypeOf(new HellaCacheResp)
    }

    val driveReq = RegInit(false.B)
    val sawFirstAbort = RegInit(false.B)
    val secondReqMemFires = RegInit(0.U(2.W))
    val successReg = RegInit(false.B)
    val cycle = RegInit(0.U(16.W))
    cycle := cycle + 1.U

    val (phaseIdle :: phaseFirstReq :: phaseFirstS2Root :: phaseFirstS2Mid :: phaseFirstS2Leaf ::
      phaseFirstStage1 :: phaseFirstAbort :: phaseWaitAbort :: phaseSecondReq :: phaseObserveSecond ::
      phaseWaitSecondResp :: phaseDone :: Nil) = Enum(12)
    val phase = RegInit(phaseIdle)

    val (actNone :: actRespS2RootTable :: actRespS2MidTable :: actRespS2Leaf ::
      actRespStage1NonLeaf :: actAbort :: Nil) = Enum(6)
    val actionD1 = RegInit(actNone)
    val actionD2 = RegInit(actNone)
    actionD2 := actionD1
    actionD1 := actNone

    when (actionD2 === actRespS2RootTable) {
      ptw.io.mem.resp.valid := true.B
      ptw.io.mem.resp.bits.data := tablePte(hostStage2L1Ppn)
    }
    when (actionD2 === actRespS2MidTable) {
      ptw.io.mem.resp.valid := true.B
      ptw.io.mem.resp.bits.data := tablePte(hostStage2L2Ppn)
    }
    when (actionD2 === actRespS2Leaf) {
      ptw.io.mem.resp.valid := true.B
      ptw.io.mem.resp.bits.data := leafPte(hostStage2LeafPpn)
    }
    when (actionD2 === actRespStage1NonLeaf) {
      ptw.io.mem.resp.valid := true.B
      ptw.io.mem.resp.bits.data := tablePte(guestNextPpn)
    }
    when (actionD2 === actAbort) {
      ptw.io.mem.s2_xcpt.ae.ld := true.B
    }

    ptw.io.requestor(0).req.valid := driveReq

    when (ptw.io.requestor(0).req.fire) {
      printf(p"REQ fire phase=$phase cycle=$cycle\n")
    }
    when (ptw.io.mem.req.fire) {
      printf(p"MEM fire phase=$phase cycle=$cycle addr=${Hexadecimal(ptw.io.mem.req.bits.addr)} second=$secondReqMemFires\n")
    }
    when (ptw.io.mem.resp.valid) {
      printf(p"MEM resp phase=$phase cycle=$cycle data=${Hexadecimal(ptw.io.mem.resp.bits.data)}\n")
    }
    when (ptw.io.requestor(0).resp.valid) {
      printf(p"PTW resp phase=$phase cycle=$cycle pf=${ptw.io.requestor(0).resp.bits.pf} gf=${ptw.io.requestor(0).resp.bits.gf} ae=${ptw.io.requestor(0).resp.bits.ae_ptw} level=${ptw.io.requestor(0).resp.bits.level}\n")
    }

    switch(phase) {
      is(phaseIdle) {
        when (cycle > 2.U) {
          driveReq := true.B
          phase := phaseFirstReq
        }
      }
      is(phaseFirstReq) {
        when (ptw.io.requestor(0).req.fire) {
          driveReq := false.B
          phase := phaseFirstS2Root
        }
      }
      is(phaseFirstS2Root) {
        when (ptw.io.mem.req.fire) {
          actionD1 := actRespS2RootTable
          phase := phaseFirstS2Mid
        }
      }
      is(phaseFirstS2Mid) {
        when (ptw.io.mem.req.fire) {
          actionD1 := actRespS2MidTable
          phase := phaseFirstS2Leaf
        }
      }
      is(phaseFirstS2Leaf) {
        when (ptw.io.mem.req.fire) {
          actionD1 := actRespS2Leaf
          phase := phaseFirstStage1
        }
      }
      is(phaseFirstStage1) {
        when (ptw.io.mem.req.fire) {
          actionD1 := actRespStage1NonLeaf
          phase := phaseFirstAbort
        }
      }
      is(phaseFirstAbort) {
        when (ptw.io.mem.req.fire) {
          actionD1 := actAbort
          phase := phaseWaitAbort
        }
      }
      is(phaseWaitAbort) {
        when (ptw.io.requestor(0).resp.valid) {
          sawFirstAbort := true.B
          driveReq := true.B
          phase := phaseSecondReq
        }
      }
      is(phaseSecondReq) {
        when (ptw.io.requestor(0).req.fire) {
          driveReq := false.B
          secondReqMemFires := 0.U
          phase := phaseObserveSecond
        }
      }
      is(phaseObserveSecond) {
        when (ptw.io.mem.req.fire) {
          secondReqMemFires := secondReqMemFires + 1.U
          when (secondReqMemFires === 1.U) {
            actionD1 := actAbort
            phase := phaseWaitSecondResp
          }
        }
      }
      is(phaseWaitSecondResp) {
        when (ptw.io.requestor(0).resp.valid) {
          assert(ptw.io.requestor(0).resp.bits.pte.ppn === expectedCorrectRootPpn,
            "PTW kept the stale root PTE after a stage2 PTE cache hit")
          assert(ptw.io.requestor(0).resp.bits.pte.ppn =/= expectedWrongRootPpn,
            "PTW kept the stale root PTE after a stage2 PTE cache hit")
          successReg := true.B
          phase := phaseDone
        }
      }
      is(phaseDone) {
        successReg := true.B
      }
    }

    assert(cycle < 512.U, "PTW stage2 cache harness timed out")
    assert(sawFirstAbort || phase =/= phaseDone, "The warm-up walk never reached the abort point")

    io.success := successReg
  }
}

class PTWStage2CacheHarness(implicit p: Parameters) extends Module {
  override def desiredName = "PTWStage2CacheHarness"
  val io = IO(new Bundle {
    val success = Output(Bool())
  })

  val dut = Module(LazyModule(new PTWStage2CacheHarnessLazy(p)).module)
  io.success := dut.io.success
}

object PTWStage2CacheRepro {
  def main(args: Array[String]): Unit = {
    val targetDir = if (args.nonEmpty) args(0) else "/home/rocket-chip/.hwe_ptw_stage2_cache/generated"
    implicit val p: Parameters = new WithHypervisor ++ new BaseSubsystemConfig
    ChiselStage.emitSystemVerilogFile(
      new PTWStage2CacheHarness,
      Array("--target-dir", targetDir),
      Array("--disable-annotation-unknown")
    )
  }
}
EOF

cat > "$CPP_FILE" <<'EOF'
#include "VPTWStage2CacheHarness.h"
#include "verilated.h"

int main(int argc, char** argv) {
  Verilated::commandArgs(argc, argv);
  VPTWStage2CacheHarness top;
  vluint64_t cycles = 0;

  top.clock = 0;
  top.reset = 1;

  while (!Verilated::gotFinish() && cycles < 1024) {
    top.clock = 0;
    if (cycles > 2) {
      top.reset = 0;
    }
    top.eval();

    top.clock = 1;
    top.eval();

    if (top.io_success) {
      return 0;
    }

    ++cycles;
  }

  return top.io_success ? 0 : 1;
}
EOF

